import torch

def gen_inputs(axes, device):
    M, K, N = axes["M"], axes["K"], axes["N"]
    return {
        "A": torch.randn(M, K, dtype=torch.float32, device=device),
        "B": torch.randn(K, N, dtype=torch.float32, device=device),
    }

def run(A, B, C):
    result = torch.matmul(A, B)
    C.copy_(result)
